package kerneldbfixture

import (
	"bytes"
	"compress/gzip"
	_ "embed"
	"io"
)

// Empty database generated by executing db.schema and RunMigrationsThrough(57).
// The published migration prefix is unchanged from v9.1.0. Keep this carrier
// frozen: deleting schema_version rows from a current database is not a downgrade.
//
//go:embed testdata/schema57.db.gz
var schema57Database []byte

// CreateSchema57 installs a genuine historical schema into a new database path.
// It does not open a current Store, which would immediately migrate the fixture.
func CreateSchema57(databasePath string) error {
	reader, err := gzip.NewReader(bytes.NewReader(schema57Database))
	if err != nil {
		return err
	}
	defer reader.Close()
	contents, err := io.ReadAll(reader)
	if err != nil {
		return err
	}
	return cloneTemplate(contents, databasePath)
}
